var e={AnimationOptions:`动画的时间设置。省略的部分保留该动画的默认值。`,"AnimationOptions.duration":"单位为 ms。布局移动默认 200，放置默认 250；`0` 关闭动画。","AnimationOptions.easing":"CSS 缓动（`'ease-out'`、`cubic-bezier(…)`）。",LayoutAnimationContext:`布局动画函数收到的参数，针对一个移动到新位置的项。`,"LayoutAnimationContext.key":`项的 key。`,"LayoutAnimationContext.element":`项的元素，已经在新位置上。`,"LayoutAnimationContext.from":`变化之前的视觉矩形（正在运行的动画显示该项的位置）。`,"LayoutAnimationContext.to":`变化之后的布局矩形。`,"LayoutAnimationContext.options":`选项给出的时间设置，已填入默认值。`,"LayoutAnimationContext.reason":"是什么移动了这个项：一次拖拽（`'drag'`：排序、放置、取消），或者非拖拽引起的数据变化（`'change'`，需开启列表的 `animateChanges`）。","LayoutAnimationContext.signal":"库中断动画时中止：项在动画结束前再次移动（下一个动画从它当前显示的位置开始），或者动画被关闭。返回的 `Animation` 会自动帮你取消。其他任何东西都要在这里停止，并立即撤销它设置的样式：紧接着就会测量布局。","LayoutAnimationContext.reducedMotion":"设置了 `prefers-reduced-motion: reduce`。此时库自己的动画不会运行；你的函数总会运行，并据此做出决定（跳过，或保留一个淡入淡出）。",LayoutAnimation:"项如何移动到新位置：`true`（默认时间）、选项、`false`（直接跳过去），或一个函数——它为一个项执行从 `from` 到 `to` 的动画，并返回它的 `Animation`、一个在动画结束时完成的 Promise，或者不返回任何东西。",DropAnimationContext:`放置动画函数收到的参数：浮层、它现在的位置和它将落到的位置。`,"DropAnimationContext.overlay":"浮层盒子；它会落到当前项的位置上。在多项拖拽中，随它一起移动的其他项的克隆（默认浮层中的克隆、自定义浮层中的 `DragPreview`）会自行落到各自的位置上（如果这是一个自定义函数，则使用默认时间）。","DropAnimationContext.from":`拖拽结束时浮层所在的位置。`,"DropAnimationContext.to":"被放下的项的最终矩形；当它没有被渲染或不可见时为 `null`（浮层淡出）。","DropAnimationContext.into":`放到一个区域（而不是可排序列表）上之后，该项不再显示，例如它被放进了另一个项（文件夹）或回收区：此时为该区域的可见矩形。默认动画会让浮层在淡出时缩进这个区域，而不是在原地淡出。`,"DropAnimationContext.reason":"`'drop'`：浮层落到放置把项放到的地方。`'cancel'`：它飞回项原来所在的地方。","DropAnimationContext.active":`结束的那次拖拽。`,"DropAnimationContext.over":"放置落到的目标（列表、放置区）；取消时为 `null`。","DropAnimationContext.options":`选项给出的时间设置，已填入默认值。`,"DropAnimationContext.reducedMotion":"设置了 `prefers-reduced-motion: reduce`。此时库自己的动画不会运行；你的函数总会运行，并据此做出决定（跳过，或保留一个淡入淡出）。",DropAnimation:"浮层在放置时如何落位、在取消时如何飞回原处：`true`（默认时间）、选项、`false`（不飞行：它停在松开的地方），或者一个函数：把 `overlay` 从 `from` 动画到 `to`，并返回它的 `Animation`、一个在动画结束时完成的 promise，或者什么都不返回。",EnterAnimationContext:"在开启了 `animateChanges` 的列表中出现的项：新添加的，或重新显示的（过滤、展开的树节点）。","EnterAnimationContext.key":`项的 key。`,"EnterAnimationContext.element":`该项的元素，已经位于它的位置上。`,"EnterAnimationContext.to":`它出现的位置（布局矩形）。`,"EnterAnimationContext.options":`选项给出的时间设置，已填入默认值。`,"EnterAnimationContext.reducedMotion":"设置了 `prefers-reduced-motion: reduce`。此时库自己的动画不会运行；你的函数总会运行，并据此做出决定（跳过，或保留一个淡入淡出）。",LeaveAnimationContext:"从开启了 `animateChanges` 的列表中离开的项：被删除的，或被隐藏的（过滤、折叠的树节点）。","LeaveAnimationContext.key":`项的 key。`,"LeaveAnimationContext.element":"该项元素的副本，显示在该项原来的位置（项本身已经不在了）：在原来的父元素中绝对定位，忽略指针，并带有 `data-dnd-leaving` 标记。你的动画结束后，库会移除它。","LeaveAnimationContext.from":`该项原来所在的位置。`,"LeaveAnimationContext.options":`选项给出的时间设置，已填入默认值。`,"LeaveAnimationContext.reducedMotion":"设置了 `prefers-reduced-motion: reduce`。此时库自己的动画不会运行；你的函数总会运行，并据此做出决定（跳过，或保留一个淡入淡出）。",EnterAnimation:"`true`、选项、`false`（项直接出现），或一个为它执行进入动画的函数。",LeaveAnimation:"`true`、选项、`false`（项直接消失），或一个为留在原处的副本执行离开动画的函数：返回它的 `Animation` 或一个 Promise，副本会在动画结束时被移除（函数什么都不返回时立即移除）。",AutoAnimationOptions:"分部分设置的 `animateChanges`：`duration` 和 `easing` 适用于所有部分；每种变化可以单独设为 `true`、选项（覆盖共享选项）、`false`，或你自己的函数。","AutoAnimationOptions.move":"位置发生变化的项（默认的 FLIP，与 `animation` 的相同；函数会替换它）。","AutoAnimationOptions.enter":`新出现的项。默认：在原地淡入。`,"AutoAnimationOptions.leave":`离开的项。默认：该项的副本在它原来的位置淡出，同时略微缩小。`,AutoAnimation:"为非拖拽引起的列表（或树）项的变化添加动画：项被添加、删除、移动（排序、打乱、在同一分组的列表之间移动）或过滤。默认关闭（`false`）；`true` 会以默认时间为移动、进入和离开的项添加动画。拖拽保留它们自己的动画（`animation`、`dropAnimation`）。在 `prefers-reduced-motion: reduce` 下，默认动画不会运行；你的函数仍然会运行（并收到 `reducedMotion: true`）。只有可见区域附近的项才会执行动画（虚拟列表中未挂载的行会被跳过）。",DragAreaOptions:"`makeDragArea` 的选项：为在区域元素内部开始的拖拽（普通可拖拽元素和可排序项都一样）设定规则，这样一个 provider 就能服务整个应用，而页面的各个部分可以按自己的方式拖拽。区域嵌套时，最近的区域优先。\n\n每个选项都接受值、ref 或 getter，并在需要时读取：按下开始时（`activation`、`disabled`）或拖拽开始时。","DragAreaOptions.axis":"在修饰器之后，把拖拽锁定在一个轴上。可拖拽元素自身的 `axis`（或其列表的）优先。","DragAreaOptions.modifiers":"拖拽的修饰器，在 provider 的之后、可拖拽元素自己的（或其列表的）之前运行：例如为面板设置 `[snapToGrid(20)]`。","DragAreaOptions.restrictToArea":"`true`：拖拽保持在区域的元素内（在修饰器之后、轴锁定之前）。","DragAreaOptions.autoScroll":"为区域的滚动容器覆盖 provider 的 `autoScroll`：滚动容器是该元素本身，或离它最近的可滚动祖先。`false` 在那里关闭自动滚动。与其他选项不同，它适用于每一次滚动该容器的拖拽，无论拖拽从哪里开始。","DragAreaOptions.activation":`按指针类型设置拖拽的激活条件，介于可拖拽元素自己的（优先）和 provider 的之间：例如在可滚动的信息流中使用更长的触摸按压。`,"DragAreaOptions.disabled":"`true`：区域内不会开始任何拖拽，其内部的区域也一样（与其他选项不同，其他选项取自最近的区域）。区域中的可拖拽元素会报告 `aria-disabled`。",DragAreaReturn:"`makeDragArea` 的返回值。","DragAreaReturn.isDragging":`从这个区域开始的拖拽正在进行（直到放置结果确定）。`,"DragAreaReturn.isAutoScrolling":`自动滚动正在滚动区域的滚动容器（该元素，或离它最近的可滚动祖先）。`,CollisionCandidate:`碰撞检测可以选中的放置目标：已启用、在页面上且没有被完全裁剪。`,"CollisionCandidate.id":`放置目标的 id。`,"CollisionCandidate.rect":`目标的可见部分：经过其滚动容器和视口裁剪。`,"CollisionCandidate.priority":"目标的 `priority`（默认 0）：目标重叠但没有嵌套时，值高的胜出。可排序项胜过容器。","CollisionCandidate.depth":`在放置目标之间的嵌套层级：顶层为 0，越深的目标值越大。`,CollisionArgs:`碰撞检测在拖拽每次移动时收到的参数。`,"CollisionArgs.pointer":`视口坐标中的指针位置，已应用修饰器。`,"CollisionArgs.overlayRect":"被拖拽的盒子（浮层，或在 `overlay: false` 时元素本身）被拖到的位置上的矩形。","CollisionArgs.candidates":"拖拽可能去往的每个放置目标，无论它的 `accept` 规则是否接受这次拖拽。","CollisionArgs.hits":`通过命中测试得到的指针下方的放置目标（遵循 z 轴顺序和 shadow root），最佳的在前。`,CollisionDetection:`返回候选 id，最佳的在前。`,ModifierArgs:`修饰器在拖拽每次移动时收到的参数。`,"ModifierArgs.transform":`相对拖拽起点的偏移量，已经过前面的修饰器处理。`,"ModifierArgs.active":`这次拖拽。`,"ModifierArgs.activeRect":`拖拽开始时被拖拽元素的矩形。`,"ModifierArgs.overlayRect":"假如浮层盒子按 `transform` 移动、并保持当前尺寸时的矩形。使用 `overlayFit: 'slot'` 时，盒子会围绕指针调整尺寸，所以它并不总是等于按 `transform` 移动后的 `activeRect`。","ModifierArgs.origin":`拖拽开始时的指针位置。`,"ModifierArgs.containerRect":`被拖拽项所在的可排序列表容器（或父元素）的当前位置（它会跟随滚动）。`,"ModifierArgs.containerShift":`拖拽开始时所在的内容自开始以来在屏幕上移动了多远：容器本身移动了（页面或它外层的容器滚动了、布局发生了偏移），以及它的内容在容器内滚动了。轴锁定把另一个轴保持在这个偏移上，所以拖拽会停留在该内容中它所在的那一行或那一列。`,"ModifierArgs.windowRect":`窗口（视口）的矩形。`,"ModifierArgs.over":"拖拽下方的放置目标，以最近一次找到的为准；不在任何目标上方时为 `null`。",Modifier:"改变被拖拽项去往的位置：接收拖拽的偏移量（`transform`）并返回新的偏移量。",SnapToGridOptions:"`snapToGrid` 的选项。","SnapToGridOptions.x":`单元格宽度，单位 px。不设置（或为 0）时，拖拽沿 x 轴自由移动。`,"SnapToGridOptions.y":"单元格高度，单位 px。不设置（或为 0）时，拖拽沿 y 轴自由移动：`{ y: 15 }` 只吸附日历事件的时间。","SnapToGridOptions.origin":"`'container'`（默认）：浮层的左上角落在从容器左上角开始绘制的网格线上（`containerRect`：可排序列表或父元素）。`'delta'`：对拖拽偏移量取整，项开始时与网格的错位会保留下来。","SnapToGridOptions.smooth":`让浮层在吸附位置之间滑动（默认 80ms）。碰撞检测仍然立即使用吸附后的位置。`,DragItem:`一个被拖拽的项：拖拽开始时的那个，或者多项拖拽中的另一个。`,"DragItem.id":`它的可拖拽元素的 id（可排序项的 key）。`,"DragItem.item":`拖拽来自可排序列表时的项对象。`,"DragItem.data":"它的 `data` 选项。","DragItem.label":"它的 `label`，即人们对它的称呼。","DragItem.type":"可拖拽元素经过规范化的 `type`；为空表示它符合任何放置目标。",Active:`进行中的拖拽：开始拖拽的那个项，以及它携带的每个项。`,"Active.id":`拖拽开始时所在项的 id。`,"Active.ids":`所有被拖拽的 id，主项在最前（多项拖拽）。`,"Active.items":`所有被拖拽的项，主项在最前。`,"Active.data":"开始拖拽的那个项的 `data`。","Active.label":"拖拽开始时那个项的 `label`，即人们对它的称呼。","Active.type":"开始拖拽的那个项经过规范化的 `type`；为空表示它适合任何放置目标。","Active.element":`拖拽开始时所在的元素。它可能会被移出文档（虚拟列表、跨列表移动）。`,"Active.rect":"拖拽开始时 `element` 的布局矩形。","Active.sensor":"拖拽的移动方式：`'pointer'` 跟随坐标点，`'keyboard'` 按项移动（`SensorActivation.type`）。","Active.external":"来自页面之外的拖拽（文件、链接、文本，或来自应用另一个窗口的项）：它携带的内容。它的 `items` 是为它生成的（`element` 是一个替身）。","Active.native":"浏览器自己的拖拽（`native`，或来自外部的拖拽）：拖拽的图像由浏览器绘制，没有浮层。",Over:`拖拽下方的放置目标。`,"Over.id":`放置目标的 id。`,"Over.data":"目标的 `data` 选项。","Over.label":"目标的 `label`，即人们对它的称呼。","Over.element":`目标的元素。`,"Over.rect":"`element` 的矩形，在拖拽期间测量。","Over.accepted":"目标的 `accept` 规则是否接收被拖拽的项。",DropDestination:"放置会把被拖拽的项放到哪里：可排序列表或树中的一个位置，与放置事件的 `to` 将给出的一致（即浮层的 `to` prop，实时更新）。","DropDestination.list":`列表或树的 id。`,"DropDestination.index":"被拖拽的项所占的索引：在列表中，或在树中 `parentKey` 下的兄弟节点之间。","DropDestination.parentKey":"树：它们将放到其下的节点；在根层级时为 `null`。","DropDestination.depth":`树：它们将处于的深度（根节点为 0）。`,DragSource:`被拖拽的项来自哪里（当来源是可排序列表时）。`,"DragSource.list":`被拖拽的项所来自的可排序列表。`,"DragSource.remove":`把被拖拽的项从它们的列表中移除（回收区）。`,DragMode:"放置会做什么：`'move'`、`'copy'`（项留在原处，放进去的是它们的副本）、`'swap'`（`behavior: 'swap'`：两个项交换位置）或 `'insert'`（普通的可拖拽元素以列表的 `createItem` 创建的项进入列表）。",DnDEvent:`拖拽事件携带的内容：监听器、provider 的事件和放置目标的钩子都会收到它。`,"DnDEvent.active":`这次拖拽。`,"DnDEvent.over":"拖拽下方的放置目标；不在任何目标上方时为 `null`。","DnDEvent.pointer":`指针的视口坐标，已经过修饰器处理。`,"DnDEvent.delta":`相对拖拽起点的偏移量，已经过修饰器处理。`,"DnDEvent.position":"被拖拽盒子的左上角在 `over` 中的位置，从其内边距边缘量起，并计入其滚动量：即能把一个绝对定位的项放到被放下位置的 `left`/`top`（面板上的便签）。下方没有目标时为 `null`。取的是浮层盒子的位置；使用 `overlay: false` 时则是元素本身的位置。","DnDEvent.mode":"放置将做什么：`'move'`、`'copy'`（列表的 `pull: 'clone'`，或拖拽来自可 `clone` 的列表的项时按住复制键）、`'swap'` 或 `'insert'`。普通放置目标可以读取它，以复制代替移动。","DnDEvent.source":`当被拖拽的项来自可排序列表时存在。`,"DnDEvent.external":"来自页面之外的拖拽：它携带的内容（`active.external`）。它的数据在放置时到来。",DnDEndEvent:"`onDragEnd`（以及目标的 `onDrop`）收到的内容：放置的事件，以及它的结果。","DnDEndEvent.dropped":`拖拽结束在所有放置目标之外时为 false。`,"DnDEndEvent.accepted":"被 `onBeforeDrop` 接受的 id（除非返回了一个子集，否则就是所有被拖拽的 id）。","DnDEndEvent.rejected":"其余被拖拽的 id：`onBeforeDrop` 没有接受它们，它们会飞回原处。全部接受时为空。","DnDEndEvent.droppedOutside":"拖出页面的拖拽（`native`）被放到别处时：那个地方对它做了什么。`'move'` 会把这些项从这里的可排序列表中拿走；`'copy'` 和 `'link'` 则保留它们。",BeforeDropResult:"`onBeforeDrop` 的决定：\n- `'accept'`（或 `true`，或不返回）：放置生效；\n- `'reject'`（或 `false`）：不放置，项飞回原处；\n- id 列表：只接受这些项，其他项飞回原处；\n- `'continue'`：不放置，拖拽继续。使用指针时，项会再次跟随指针（不需要按住按键），下一次松开——也就是一次点击——会放下它；使用触摸时，会重新拿起它；使用键盘时，照常移动它。Escape 会取消它。放置时会再次询问 `onBeforeDrop`。",AcceptContext:"函数形式的 `accept` 规则被调用时收到的参数。","AcceptContext.active":`这次拖拽。`,"AcceptContext.items":`所有被拖拽的项。`,"AcceptContext.types":`所有被拖拽项的类型合在一起。`,AcceptRule:"`'*'` 或省略表示接收所有。没有类型的项符合任何字符串规则（与 v2 的 `groups: []` 行为一致）。",AcceptMode:"`'all'`：每个被拖拽的项都必须匹配；`'some'`：至少一个（其余的可以在 `onBeforeDrop` 中拒绝）。",KeyboardMoveContext:"按下方向键时，调用 `getKeyboardCoordinates` 所传入的参数。","KeyboardMoveContext.active":`这次拖拽。`,"KeyboardMoveContext.pointer":`拖拽当前所在的位置，使用视口坐标。`,"KeyboardMoveContext.direction":`所按方向键的单位向量。`,DnDMonitor:"provider 下每次拖拽的钩子（`useDnDMonitor`）。","DnDMonitor.onDragStart":`拖拽在激活之后开始了。`,"DnDMonitor.onDragMove":`拖拽移动了（每帧最多一次）。`,"DnDMonitor.onDragOver":`拖拽下方的目标变了。`,"DnDMonitor.onBeforeDrop":"在放置提交之前运行（参见 `BeforeDropResult`）：`'reject'` 拒绝它，返回 id 则只接受其中一部分。","DnDMonitor.onDragEnd":"放置完成后的通知：可排序列表已经运行了它们的 `onDrop` 并完成了写入。","DnDMonitor.onDragCancel":`拖拽被取消，或者它的放置被拒绝：项飞回原处。`,"DnDMonitor.onDragResume":"`onBeforeDrop` 返回了 `'continue'`：没有发生放置，拖拽继续。","DnDMonitor.onDragSettle":"已结束的拖拽的浮层已经落位：在它的放置动画（或取消时的飞回）之后触发，参数是 `onDragEnd`（一个 `DnDEndEvent`）或 `onDragCancel` 收到的那个事件。下一次拖拽可能已在此期间开始：拖拽不会等待落位。","DnDMonitor.getKeyboardCoordinates":`键盘拖拽：某个方向键对应的下一个指针位置（例如下一个可排序位置）。`,DnDSelection:`选中的可拖拽元素，按 id 记录：拖拽其中一个会带上全部（多项拖拽）。由于按 id 保存，选中集合在元素卸载后依然保留（虚拟列表）。`,"DnDSelection.ids":`选中的 id，响应式。`,"DnDSelection.has":"`id` 是否被选中。","DnDSelection.add":`选中这些 id。`,"DnDSelection.delete":`取消选中这些 id。`,"DnDSelection.toggle":"选中或取消选中 `id`；`force: true` 选中它，`false` 取消选中它。","DnDSelection.set":`只选中这些 id，其他都不选。`,"DnDSelection.clear":`取消选中所有 id。`,DnDState:"放置结果确定时，拖拽状态即告结束：`active`、`over` 和 `pointer` 变为 `null`（放置目标也不再接收），而浮层仍在以动画方式就位。派生的 UI 永远不会把旧的拖拽和新数据混在一起。在异步的 `onBeforeDrop` 做决定期间，状态保持松开时的样子，但页面已退出拖拽模式：它自己的光标和文本选择恢复正常（确认对话框可以照常工作），浮层停在被放下的位置等待。\n\n拖拽进行时 `status` 为 `'dragging'`；否则，在放置结果待定或仍有浮层在落位时为 `'dropping'`；否则为 `'idle'`（`'activating'` 和 `'selecting'` 除外）。新的拖拽不会等待落位：它立即开始，落位在它周围完成。","DnDState.status":"provider 当前在做什么（见 `DnDStatus`）。","DnDState.active":"进行中的拖拽；没有拖拽时为 `null`，放置一旦确定也变为 `null`。","DnDState.over":"拖拽下方的放置目标；不在任何目标上方时为 `null`。","DnDState.pointer":"视口坐标中的指针位置，已应用修饰器；没有拖拽时为 `null`。","DnDState.position":"被拖拽盒子的左上角在 `over` 中的实时位置：即每次移动时的 `DnDEvent.position`。下方没有目标时为 `null`。浮层组件可以读取它来显示将落到哪里（日历上的某个时间）。","DnDState.activation":"`progress`：在 `status` 为 `'activating'` 时，按下距离满足激活约束的进度，从 0 到 1：例如在长按期间逐渐填满的圆环。","DnDState.isAutoScrolling":`自动滚动正在移动某个容器。`,"DnDState.selection":"选中的可拖拽元素（见 `DnDSelection`）。","DnDState.cancel":`取消拖拽（它会飞回原处），或取消等待中的激活。`,"DnDState.addWindow":"拖拽在 `view` 中也能工作：应用的另一个窗口，显示应用的一部分（用 `window.open` 打开的弹出窗口、分离出来的面板、Document Picture-in-Picture 窗口）。挂载时就渲染到其中的组件会被自动找到；Teleport 之后才移过去的内容则不会，所以打开窗口时要把它告诉 provider。在窗口关闭或返回的函数被调用之前，provider 会监听它、把样式注入其中，在其中开始的拖拽也会留在其中（它的视口、它的放置目标、它的 `<body>` 中的浮层）。带有 `native` 的项还可以在窗口之间穿梭。",DraggableOptions:"`makeDraggable` 的选项。除 `canDrag` 外，每个选项都接受值、ref 或 getter（`overlay`、`dropAnimation`：值或 ref），并在需要时读取，所以变化最迟在下一次拖拽时生效。","DraggableOptions.id":"稳定的 id。在元素会被回收的虚拟列表中，传入 getter。默认：`useId()`，在服务端和客户端渲染之间保持稳定，但每个组件实例都不同。","DraggableOptions.data":"拖拽要携带的任何内容：事件和放置目标以 `active.data` 读取它。","DraggableOptions.label":"人们对它的称呼：屏幕阅读器文本会说出它，而不是 id（`Picked up Tomato`）。事件以 `active.label` 和在 `items` 中携带它。","DraggableOptions.type":"它的一个或多个类型，由放置目标的 `accept` 规则来匹配。没有类型时它适合任何目标。","DraggableOptions.disabled":"`true`：它不能被拖拽（会报告 `aria-disabled`）。","DraggableOptions.handle":`可拖拽元素内部用于开始拖拽的元素或选择器（它也会得到相关属性）。`,"DraggableOptions.activation":"覆盖 provider 的 `activation`。在按下开始时读取。","DraggableOptions.canDrag":`额外的关卡，例如只在按住某个键时才能拖拽。`,"DraggableOptions.overlay":"`true`（默认）：浮层跟随指针，由 provider 的 `#overlay` 插槽渲染，或者是元素的克隆。组件：浮层以 `OverlayProps` 渲染它，优先于插槽。`false`：没有浮层，元素本身通过返回的 `transform` 移动。值或 ref（函数即函数式组件，所以 `(props) => <Card {...props} />` 也可以）。是否有浮层在拖拽开始时决定；在拖拽过程中切换的 ref 会立即替换组件（见 provider 的 `overlayTransition`）。拖拽位于放置目标上方时，目标的 `overOverlay` 优先。克隆会排除 UI 库的按下效果（水波纹），以及内部任何标记了 `data-dnd-no-clone` 的元素。","DraggableOptions.dropAnimation":"这个元素的拖拽结束时浮层如何落位，替代 provider 的 `dropAnimation`；放置目标的 `overDropAnimation` 优先。值或 ref（函数即动画），在放置时读取。","DraggableOptions.modifiers":"从这里开始的拖拽的修饰器，在 provider 的 `modifiers` 之后应用：例如在一个其他拖拽都可以自由移动的页面上，为某个元素设置 `[restrictToVerticalAxis]`。在拖拽开始时读取。","DraggableOptions.axis":"把从这里开始的拖拽锁定在一个轴上：`'x'` 只水平移动，`'y'` 只垂直移动。锁定在 `modifiers` 之后执行（相当于把 `restrictToHorizontalAxis` / `restrictToVerticalAxis` 放在最后），所以无论修饰器做什么，锁定都成立。在拖拽开始时读取。","DraggableOptions.keyboardMode":`自由拖拽中的方向键：按像素移动（默认），或在接收它的放置目标之间跳转。每次按下方向键时读取。`,"DraggableOptions.attributes":"设置 role/tabindex/aria-* 属性（默认 `true`），永远不会覆盖用户自己设置的。provider 的操作说明 id 会作为又一个 token 加入已有的 `aria-describedby`（同一元素上 UI 库的提示框会保留它自己的），并且只有这个 token 会被移除。实时生效：关闭后，库设置的属性会被移除。","DraggableOptions.native":"用鼠标拖拽它就是浏览器自己的拖拽，可以离开页面：拖到桌面上，拖进另一个应用或标签页，拖进应用的另一个窗口。在页面上它照常工作（目标、腾出位置的列表），但拖拽的图像由浏览器绘制，代替浮层。触摸拖拽和键盘拖拽仍是本库的拖拽。`true` 把 `label` 作为文本携带。在按下开始时读取。`canDrag` 在按下时询问；鼠标移动多远后开始拖拽由浏览器决定（`activation` 对它不适用）。",DraggableReturn:"`makeDraggable` 的返回值。","DraggableReturn.id":"可拖拽元素的 id：`id` 选项，或为它生成的 id。","DraggableReturn.isDragging":`它正在被拖拽（也包括作为多项拖拽中的另一个项），或者它的浮层仍在落位。`,"DraggableReturn.transform":"使用 `overlay: false` 时要应用的偏移量：拖拽的偏移量，减去元素所在的内容自开始以来移动的距离（页面或某个容器滚动了），这样元素会一直停在指针下方。","DraggableReturn.selected":`它在 provider 的选中集合中：拖拽一个选中的项会带上全部。对它赋值即可选中或取消选中。`,Placement:"指针位于被悬停的放置目标的哪几个半区（`DroppableReturn.placement`）。","Placement.top":`在上半部分。`,"Placement.right":`在右半部分。`,"Placement.bottom":`在下半部分。`,"Placement.left":`在左半部分。`,DroppableOptions:"`makeDroppable` 的选项。\n\n**放进项中**。可排序项的元素上（或其内部）的放置目标和其他地方的一样工作，只有一条规则，适用于该项所在的列表本会对拖拽进行排序的时候：只有指针位于项的中间（沿列表轴向的 25–75%；网格中为 x 方向）时它才生效，在那里放置会进入目标，列表不会为它移动。靠近项的边缘时，列表照常排序。`accept` 拒绝该拖拽的目标会被排除，所以列表在该项上方照常排序，就像在其他项上方一样（无需禁用它）。键盘会先停在这样的目标上，然后才越过它所在的项。拖拽永远不会以它携带的东西为目标：被拖拽项之中（或之上）的目标不算，被拖拽项落入的位置中的目标也不算。要在 `onDrop` 中把这些项从它们的列表中移出，调用 `e.source.remove()`。\n\n除回调外，每个选项都接受值、ref 或 getter（`accept`、`overOverlay`、`overDropAnimation`：值或 ref），并在拖拽寻找目标时实时读取。","DroppableOptions.id":"默认：`useId()`，在服务端和客户端渲染之间保持稳定。","DroppableOptions.data":"关于这个目标的任何信息：事件以 `over.data` 携带它。","DroppableOptions.label":"人们对它的称呼：屏幕阅读器文本会说出它，而不是 id（`over Trash`）；事件以 `over.label` 携带它。","DroppableOptions.accept":`这个目标接收什么。在可排序项内部时，拒绝这次拖拽的目标会让列表在它上方排序。值或 ref：函数即规则。`,"DroppableOptions.acceptMode":"默认为 `'all'`。","DroppableOptions.disabled":"`true`：拖拽经过它时就像它不存在一样。","DroppableOptions.priority":`目标重叠但不嵌套时，值较高的优先（默认 0）。可排序项胜过容器。`,"DroppableOptions.overOverlay":"当这个目标接受的拖拽位于它上方时，浮层显示什么：一个获得 `OverlayProps` 的组件，代替拖拽自己的浮层（被拖拽项的组件、provider 的插槽或克隆）渲染，并把后者作为默认插槽获得，可以包裹它，也可以省略它（`<slot />`）。放置落到这里时它保持显示。没有浮层的拖拽（`overlay: false`）仍然没有浮层。值或 ref，实时读取；组件的切换使用 provider 的 `overlayTransition` 动画。（在可拖拽元素、项和列表上，`overlay` 是拖拽自己的浮层；可排序列表和树也以 `overOverlay` 接受这个选项。）","DroppableOptions.overDropAnimation":"浮层被放到这里时如何落位，替代被拖拽项和 provider 的 `dropAnimation`：`false` 让它停在放下的地方（浮层组件自己的动画，比如溅开，会在那里播放），函数则为它添加动画。值或 ref，在放置时读取。","DroppableOptions.onDragEnter":"拖拽来到了这个目标上方，无论它是否接受这次拖拽（`event.over.accepted`）。","DroppableOptions.onDragLeave":`拖拽离开了这个目标。`,"DroppableOptions.onBeforeDrop":"在这个目标上的放置生效之前询问，位于监听器的 `onBeforeDrop` 之后，前提是它接受这次拖拽（见 `BeforeDropResult`）。可以是异步的：浮层在松开的地方等待。抛出错误会拒绝这次放置。","DroppableOptions.onDrop":"这个目标上的放置已生效：执行它所代表的操作（移动项、上传文件）。当 `onBeforeDrop` 只接受了部分被拖拽的项时，`event.accepted` 是它们的 id，`event.rejected` 是其余的 id，这些项会飞回原处；`active` 仍然是整个拖拽。","DroppableOptions.external":"接收来自页面之外的拖拽：来自桌面的文件、来自另一个应用或标签页的链接或文本（浏览器的拖放）。它们和本库的拖拽一样工作（`isOver`、`isAccepting`、各个事件），放置时 `e.external` 中有它们的数据。没有 `external` 的目标会忽略它们。值、ref 或 getter，实时读取。",DroppableReturn:"`makeDroppable` 的返回值。","DroppableReturn.id":"目标的 id：`id` 选项，或为它生成的 id。","DroppableReturn.isOver":"有拖拽位于它上方（使用 `external` 时，也包括来自页面之外的拖拽）。","DroppableReturn.isAccepting":`有东西正在被拖拽，并且这个目标接收它。`,"DroppableReturn.placement":`悬停时，指针相对于目标各半部分的位置。`,DnDProvider:"管理在它内部渲染的所有内容的拖拽：输入、浮层、选中集合、自动滚动和屏幕阅读器播报（见 `DnDProviderProps`）。",DragPreview:"一个被拖拽项的默认克隆（见 `DragPreviewProps`）。自定义浮层用它自行排布多个项；默认浮层用它显示多项拖拽。",makeDraggable:`让元素可拖拽。默认是自由拖拽；可排序列表构建在它之上。`,makeDroppable:`让元素成为放置目标。`,useDnD:`用于自定义 UI 的只读拖拽状态（高亮有效目标、加载指示、进度）。`,useDnDMonitor:`订阅 provider 下每次拖拽的事件，持续到调用它的组件（或 effect 作用域）销毁为止。`,useDnDContext:"这个组件上方的 provider，作为供 `provideDnDContext` 使用的不透明句柄：它把 provider 桥接到 shadow root 和独立的 Vue 应用中。",provideDnDContext:"把一个 provider（来自 `useDnDContext()`）共享给另一个 Vue 应用，例如挂载在 shadow root 中的应用。",makeSortableList:"让容器成为可排序列表。渲染返回的 `items`（草稿顺序），而不是你的数组：放置结果会在 `onDrop` 之后写回 `options.items`，除非 `event.preventDefault()` 把 `event.result` 留给你处理。",makeSortableItem:"让元素成为可排序列表或树中的一行：它可以被拖拽、腾出位置并落到自己的位置上。在调用了 `makeSortableList`（或 `makeSortableTree`）的组件内部渲染的组件中调用它；如果那里创建了多个列表，这一行会加入元素包含它的最内层列表。用 `item`（由列表的 `getKey` 生成 key，默认 `item.id`）或 `id` 标识这一行。",makeSortableTree:"让容器成为可排序树。用调用 `makeSortableItem` 的行组件渲染返回的 `items`（草稿顺序中的可见节点，按 `depth` 缩进）。放置时，在 `onDrop` 之后，被移动的节点（连同它们的子树）会写入 `options.items`，除非 `event.preventDefault()` 把 `event.result` 留给你处理。",makeSelectionArea:'让元素成为框选区域，用于选择其中的可拖拽元素。选框由你自己渲染：`<div v-if="isSelecting" class="band" :style="style" />`。',makeDragArea:"让元素成为拖拽区域：在它内部开始的拖拽（可拖拽元素和可排序项）遵循它的规则，见 `DragAreaOptions`。这样一个 provider 就能服务整个应用，其中的看板、画布和信息流各自以自己的方式拖拽。区域嵌套时，最近的区域胜出。",defineSensor:"定义一个传感器（见 `Sensor`）：它只帮助推导类型，并原样返回参数。",useSensor:"在上方的 provider 中运行一个传感器，与 provider 的 `sensors` 并列，持续到调用它的组件（或 effect 作用域）销毁为止。卸载时它的拖拽会被取消。",pointerSensor:"通过 Pointer Events 支持鼠标、触摸和触控笔。默认在 `sensors` 中。",keyboardSensor:"Space/Enter、方向键和 Escape（可通过 provider 的 `keyboard` 选项重新绑定）。默认在 `sensors` 中；即使设置了 `keyboard: false`，它也会用 Escape 取消指针拖拽和自定义拖拽。",pointerFirst:`默认：指针下方的目标，否则是浮层重叠的目标。`,pointerWithin:`指针下方的目标，来自命中测试：遵循 z-order、浮层和 shadow root。`,rectIntersection:`与浮层重叠的目标：先比优先级，再比嵌套深度，最后比交并比（intersection over union）。`,closestCenter:`所有目标，按中心之间的距离排序。`,closestCorners:`所有目标，按各角之间的距离之和排序（适合堆叠的目标，例如看板的列）。`,restrictToVerticalAxis:"只在垂直方向移动：水平方向上，无论页面如何滚动，它都跟随开始时所在的内容（`containerShift`）。`axis: 'y'` 选项做的是同样的事，并且最后应用。",restrictToHorizontalAxis:"只在水平方向移动：垂直方向上，无论页面如何滚动，它都跟随开始时所在的内容（`containerShift`）。`axis: 'x'` 选项做的是同样的事，并且最后应用。",restrictToWindowEdges:`把浮层限制在窗口内。`,restrictToParent:`把浮层限制在拖拽开始时所在的容器内：可排序列表（而不是它的 DOM 父元素），对于普通的可拖拽元素则是父元素。`,restrictToElement:`把浮层限制在某个元素内：元素本身、ref 或 getter。`,restrictToFirstScrollableAncestor:`把浮层限制在被拖拽元素的第一个可滚动祖先元素内。`,snapToGrid:"把浮层吸附到网格上最近的单元格：数字表示正方形单元格的尺寸；选项可以分别设置每个轴、网格的起点，以及在单元格之间的滑动（`SnapToGridOptions`）。",snapCenterToCursor:`让浮层中心对准指针，而不是保持抓取时的偏移。`,ExternalFile:"来自外部的拖拽中的一个文件，即询问 `ExternalAccept.files` 时传入的形式。文件悬停在页面上方时，浏览器只告知它们的类型：`name` 和 `size` 在放置时到来。","ExternalFile.type":"它的 MIME 类型（`image/png`）；浏览器无法判断时为 `''`。","ExternalFile.name":"带扩展名的文件名（`notes.md`），在放置时可用。","ExternalFile.size":`以字节为单位的大小，在放置时可用。`,ExternalAccept:"放置目标、列表或树从来自页面之外的拖拽中接收什么：来自桌面的文件、来自另一个应用或标签页的链接或文本（`external`）。","ExternalAccept.files":"文件：`true` 接收任何文件。或者按 `<input accept>` 的写法：MIME 类型（`image/*`、`application/pdf`）和扩展名（`.md`），可以是逗号分隔的字符串或列表；扩展名在放置时检查。或者是一个对每个文件逐一询问的函数（返回 `false` 表示拒绝该文件）。从不接收文件夹。","ExternalAccept.multiple":"一次接收多个文件（默认 `true`）；`false` 会拒绝多于一个文件的拖拽。","ExternalAccept.links":"链接（`text/uri-list`）：从另一个标签页拖来的地址、来自某个页面的链接。","ExternalAccept.text":"纯文本（`text/plain`）：从另一个应用拖来的一段选中内容。","ExternalAccept.types":`它接收的其他 MIME 类型，写法与其他应用提供它们时完全一致。`,ExternalData:"来自页面之外的拖拽（`Active.external`、`DnDEvent.external`）。拖拽进行时，浏览器只告知它携带了什么，而不给出数据：文件、链接和文本在放置时到来（`ready`）。","ExternalData.types":"它提供的 MIME 类型（`Files`、`text/uri-list`、`text/plain`、某个应用自己的类型）。","ExternalData.fileTypes":"它的文件的 MIME 类型，每个文件一个（浏览器无法判断时为 `''`）。","ExternalData.files":`放置时：目标接收的文件（不含文件夹和被拒绝的文件）。`,"ExternalData.urls":"放置时：它的链接（`text/uri-list`）。","ExternalData.text":`放置时：它的纯文本。`,"ExternalData.html":`放置时：它的 HTML。`,"ExternalData.getData":"放置时：它提供的任意类型的数据（放置之前，以及对于它不提供的类型，为 `''`）。","ExternalData.ready":`它已被放下：上面的数据已经可用。`,"ExternalData.group":"从应用另一个窗口拖进来的本库的项（`native`）：它们的可排序分组的名称。该分组的列表会接收它们，就像它们来自自己的某个列表一样；`active.items` 中包含它们。",NativeDragOptions:"可以用鼠标拖出页面的可拖拽元素或可排序项（`native`）：拖到桌面上，拖进另一个应用、另一个标签页、应用的另一个窗口。","NativeDragOptions.data":"其他应用和页面得到的内容：按 MIME 类型给出的文本，形如 `{ 'text/plain': title, 'text/uri-list': url }`。在拖拽开始时读取。可排序项还会携带它们自身，供应用另一个窗口中同一分组的列表使用。","NativeDragOptions.effect":"这次拖拽允许它被放到的地方做什么（`effectAllowed`）。默认 `'copyMove'`：移动会把这些项从这里的列表中拿走，复制则保留它们。",Key:`id 或 key：可拖拽元素、放置目标、列表或列表项的。`,MaybeReadonlyRefOrGetter:"值、getter 或任何 ref（可写、浅层、computed、只读——例如来自 `useTemplateRef` 的），库只会读取它。与 Vue 的 `MaybeRefOrGetter` 不同，在需要 `string | number` 的地方它接受 `Ref<string>`。",MaybeReadonlyRef:"值或任何 ref，用于函数本身就是一种值的选项（浮层组件、accept 规则、自定义动画），因此无法区分 getter。把组件放在 `shallowRef`（或 computed）中：Vue 不能把它们变成响应式的。",MaybeElement:"元素：HTML 或 SVG 元素，或组件实例（它的根元素 `$el`），就像模板引用给出的那样。还没有元素（尚未挂载）时为 `null` 或 `undefined`。",MaybeElementRef:"组合式函数作用的元素（`makeDraggable(target)`）：元素本身、模板引用（`useTemplateRef`）或 getter。它可以变化（`v-if`）：本库会跟随它。",Coordinates:"一个点或一个偏移量，单位 px：从视口左上角算起的位置，或从拖拽开始处算起的偏移量（`delta`、`transform`）。","Coordinates.x":`水平方向，向右增大。`,"Coordinates.y":`垂直方向，向下增大。`,Size:`宽度和高度，单位 px。`,"Size.width":`宽度，单位 px。`,"Size.height":`高度，单位 px。`,Rect:"一个盒子，单位 px，使用视口坐标，与 `getBoundingClientRect()` 给出的一致。","Rect.top":`上边缘，从视口顶部算起。`,"Rect.left":`左边缘，从视口左侧算起。`,"Rect.width":`宽度。`,"Rect.height":`高度。`,"Rect.right":"右边缘，从视口左侧算起：`left + width`。","Rect.bottom":"下边缘，从视口顶部算起：`top + height`。",MaybePromise:"一个值，或该值的 promise：可能是异步的钩子所返回的（`onBeforeDrop`）。",DnDStatus:"provider 当前在做什么：\n- `'idle'`：什么都没做；\n- `'activating'`：按下正在等待满足激活约束（一段距离、一次长按）；\n- `'dragging'`：拖拽进行中；\n- `'dropping'`：放置正在确定中（异步的 `onBeforeDrop`），或浮层仍在落位；\n- `'selecting'`：选择区域正在画选框。",SensorType:"拖拽如何移动，无论由哪个传感器驱动（`SensorActivation.type`）：`'pointer'` 跟随坐标点，`'keyboard'` 按项移动。",PointerKind:"按下的指针类型（`PointerEvent.pointerType`）：激活按类型设置。",ActivationConstraint:"按下在变成拖拽之前必须满足的条件：移动 `distance`，或按住 `delay`，以先满足者为准。都不设置：拖拽立即开始。","ActivationConstraint.distance":`拖拽开始前指针必须移动的像素数。`,"ActivationConstraint.delay":`拖拽开始前指针必须按住的毫秒数。`,"ActivationConstraint.tolerance":"与 `delay` 一起使用：会中止激活的移动距离（px），这样页面可以滚动。",ActivationOptions:"按指针类型设置。默认值：鼠标为 `{ distance: 4 }`（在手柄上立即开始），触控笔为 `{ distance: 4 }`，触摸为 `{ delay: 200, tolerance: 5 }`。",AnnouncedPosition:"可排序列表或树（其可见行）中的一个位置：`index` 从 0 开始计数，总数为 `length`。","AnnouncedPosition.list":`列表或树的 id。`,"AnnouncedPosition.label":"列表的 `label`，即人们对它的称呼。","AnnouncedPosition.index":"位置，从 0 开始：内置文本播报的是 `index + 1`。","AnnouncedPosition.length":`列表共有多少个位置。`,AnnouncementContext:`播报所涉及的、事件之外的信息：供你自己的文本（其他语言、其他措辞）表达内置文本所表达的内容。`,"AnnouncementContext.position":`在可排序列表或树中：被拖拽项所在的位置。开始时，是它们被拿起的位置；移动时，是它们将要落到的位置（在列表之外时没有）；结束时，是它们落到的位置，或返回的位置。`,"AnnouncementContext.partner":`交换：与被拖拽项交换的那个项，以及它现在的位置。`,"AnnouncementContext.count":`这次拖拽携带了多少项。`,"AnnouncementContext.copy":"这次拖拽是复制（`group.pull: 'clone'`、复制键）。",Announcements:"给屏幕阅读器的文本，按事件区分。返回 `undefined` 使用内置文本，返回 `''` 则不播报。`context` 包含可排序列表的内置文本所播报的位置。\n\n文本由 provider 的实时区域（live region）播报（移动要等拖拽停留 500 ms 之后）；`undefined` 把该事件交给下一个来源（集成提供的文本，例如可排序列表的位置，然后是默认文本）。拿起时找到的目标不会播报移动：此时还没有任何东西移动。","Announcements.onDragStart":`拖拽开始了。`,"Announcements.onDragOver":`拖拽移到了另一个目标上方，或列表中的另一个位置（停留 500 ms 之后）。`,"Announcements.onDragEnd":`放置已生效，或拖拽在所有目标之外结束。`,"Announcements.onDragCancel":`拖拽被取消，或者它的放置被拒绝。`,"Announcements.onDragResume":"`onBeforeDrop` 返回了 `'continue'`：拖拽继续。",Announcer:`某个集成（可排序列表）的文本，以及它为 provider 自身的文本所知道的上下文。`,KeyboardOptions:"键盘拖拽（provider 的 `keyboard`）：它们的按键，以及自由拖拽的步长。","KeyboardOptions.keys":"用于拿起（`start`）、放下和取消的按键，以 `KeyboardEvent.code`（`'Space'`、`'KeyW'`）或 `.key`（`'Enter'`、`'w'`）表示。默认：Space 和 Enter 拿起和放下，Escape 取消。方向键始终用于移动。","KeyboardOptions.step":`自由（非可排序）拖拽中每按一次方向键移动的像素数。默认 25。`,AutoScrollOptions:"拖拽靠近容器边缘时容器如何滚动（provider 的 `autoScroll`）。","AutoScrollOptions.threshold":`边缘区域，以容器尺寸的比例表示。默认 0.2（限制在 24–96px 之间）。`,"AutoScrollOptions.maxSpeed":`最大速度，单位为每 16ms 帧的像素数。`,"AutoScrollOptions.acceleration":"指针位于容器边缘时的速度，单位为每帧 px：在边缘区域内更慢，越过边缘更快，最高到 `maxSpeed`。默认 10。",HapticPattern:"一次振动（`navigator.vibrate`）：以 ms 为单位的时长，或一个开/关模式。`true` 是默认振动（10ms；`refuse` 为 `[20, 40, 20]`），`false` 或 `0` 表示不振动。",HapticsOptions:`触摸拖拽何时振动。只有由触摸发起的拖拽会振动；在浏览器无法振动（iOS Safari）或阻止振动（页面上还没有过点击）的地方，什么都不会发生。`,"HapticsOptions.start":"拖拽在长按之后开始时。默认 `true`。","HapticsOptions.enter":"拖拽进入一个接收它的放置目标（列表、区域）时。默认 `false`。","HapticsOptions.drop":"放置生效时。默认 `false`。","HapticsOptions.refuse":"放置被拒绝（被目标或 `onBeforeDrop`）、项飞回原处时。默认 `false`。",DnDProviderProps:"`DnDProvider` 的 props。大多数在 provider 需要时读取：修改其中一个，下一次拖拽就会使用它。","DnDProviderProps.collision":"如何选择拖拽下方的目标。默认 `pointerFirst`；也可以用另一个内置的（`closestCorners`）或你自己的。","DnDProviderProps.modifiers":`用于每次拖拽的修饰器，最先应用：拖拽区域、可拖拽元素和列表的修饰器在其后。`,"DnDProviderProps.animation":`可排序列表的默认 FLIP 动画。`,"DnDProviderProps.dropAnimation":"浮层在放置时如何落位、在取消时如何飞回原处，在没有更近的设置时使用：放置目标的 `overDropAnimation` 最先，然后是被拖拽项自己的（或它所在列表的），最后才是这个。","DnDProviderProps.animateChanges":"可排序列表和树的默认 `animateChanges`：为非拖拽引起的项的变化添加动画。默认关闭。","DnDProviderProps.autoScroll":"拖拽靠近容器和页面边缘时滚动它们。默认 `true`；选项用于调整，`false` 关闭。列表、树和拖拽区域可以覆盖它。","DnDProviderProps.activation":"按下在变成拖拽之前必须满足的条件，按指针类型设置（默认值见 `ActivationOptions`）。拖拽区域、列表、树、项和可拖拽元素可以覆盖它。","DnDProviderProps.keyboard":"键盘拖拽：它们的按键和步长。`false` 关闭键盘拖拽；Escape 仍然可以取消任何拖拽。","DnDProviderProps.sensors":"由什么把输入转换为拖拽。默认为 `[pointerSensor, keyboardSensor]`：可以去掉其中一个、包装或替换它，或者添加你自己的（`defineSensor`）。键盘传感器还负责用 Escape 取消任何拖拽；`keyboard: false` 会关闭它的拖拽，但保留这一功能。这个列表随时可以变化：离开列表的传感器会停止，并取消它们的拖拽。","DnDProviderProps.haptics":"触摸拖拽的振动。默认：拖拽在长按之后开始时短暂振动一次；传入对象可以添加其他振动（`enter`、`drop`、`refuse`）；`false` 关闭全部振动。","DnDProviderProps.copyModifier":"把移动变成复制的按键（KeyboardEvent.key）。默认为 `'Alt'`；`null` 表示禁用。","DnDProviderProps.overlayTo":"浮层渲染到哪里：选择器或元素。默认 `'body'`。模态 `<dialog>` 位于页面其余部分之上：在其中拖拽时，浮层需要渲染到它里面。","DnDProviderProps.overlayFit":"拖拽时浮层的尺寸。`'slot'`（默认）：它跟随项将落入的位置，所以经过另一个列表时它会采用那个列表中项的尺寸，放置时也不需要调整尺寸。它围绕指针调整尺寸，指针始终位于盒子中相同的比例位置。`'source'`：保持被拖拽元素的尺寸。默认浮层的内容会按新尺寸重新布局；它永远不会被缩放。","DnDProviderProps.overlayPreviews":"多项拖拽：拿起时有多少个被拖拽项获得克隆，即抓起的项以及按放置顺序与它相邻的其他项。默认 5；`'all'` 克隆每一个已渲染的项。默认浮层显示这些克隆，并为其余的项计数（`+N`）；在你自己的布局中，`DragPreview` 为没有克隆的项渲染它的插槽。每个克隆都会飞：取消时飞回它的项，放置时飞到它的位置，放置进某个区域时依次飞入该区域。克隆是一起生成的，每次快照过程只为全部克隆做一次布局，但每个克隆都要读取它的样式：在慢速手机上留意很长的项。","DnDProviderProps.overlayTransition":"拖拽过程中浮层从一个组件换成另一个组件的方式（放置目标的 `overOverlay` 接管，或 `overlay` ref 被切换）：`true`（默认）在 150 ms 内交叉淡入淡出，`false` 立即替换，对象则是包裹内容根元素的 Vue `<Transition>` 的 props（`name`、`mode`，以及用于 GSAP 或 motion 的 JS 钩子）。没有 `mode: 'out-in'` 时两者会同时显示：给离开的那个设置 `position: absolute`（`.<name>-leave-active`），让它们在盒子里叠在一起。","DnDProviderProps.overlayClass":"浮层内容（`[data-dnd-overlay-content]`）的 class，即填满浮层盒子的那个元素：库移动盒子并调整其尺寸时，要整体添加动画的就是它。它上面的过渡在拖拽拿起时从 `@starting-style` 开始运行，落位时反向运行（`[data-dnd-overlay='dropping']`）：放置会等待它完成。普通 CSS 要在 `<style scoped>` 之外（或用 `:global(...)`）才能选中它，Tailwind 则用 `starting:` 和 `in-data-[dnd-overlay=dragging]:`。","DnDProviderProps.announcements":"为部分事件提供自己的文本（参见 `Announcements`）；`false` 让实时区域保持静默。","DnDProviderProps.screenReaderInstructions":"如何用键盘拖拽，屏幕阅读器会为每个可拖拽元素读出（它的 `aria-describedby`）。默认：关于 Space、Enter、方向键和 Escape 的英文说明。","DnDProviderProps.defaultStyles":"注入默认外观：零优先级、分层的 CSS，让占位元素和多项拖拽留在原处的项变淡（`opacity: 0.4`）。默认 `true`；`false` 把外观交给你。拖拽所需的样式无论如何都会注入：拖拽期间禁止选中文本和滚动锚定（虚拟列表依赖于此）、拖拽光标（`--dnd-cursor`），以及 iOS 上长按时不弹出链接菜单。",DnDContext:"`useDnDContext()` 返回的 provider，用来交给 `provideDnDContext()`：之后另一个 Vue 应用（例如挂载在 shadow root 中的应用）就能与同一个 provider 协同工作。它是不透明的：没有公开成员，所以永远不会随库的内部实现而变化。",OverlaySlotProps:"浮层显示的内容：provider 的 `#overlay` 插槽和浮层组件（可拖拽元素、可排序项、列表和树的 `overlay` 选项）的 props。","OverlaySlotProps.active":`这次拖拽。`,"OverlaySlotProps.items":`所有被拖拽的项，主项在最前：整个多项拖拽只用一个浮层。`,"OverlaySlotProps.over":"拖拽下方的放置目标。已确定的放置执行动画期间，是它要落到的目标（保持放置那一刻的状态）；被取消的拖拽飞回原处时为 `null`。","OverlaySlotProps.accepted":"`over` 是否接收被拖拽的项；下方没有目标时为 `false`。","OverlaySlotProps.status":"`'dragging'`，然后在浮层落位（或飞回原处）时为 `'dropping'`。","OverlaySlotProps.mode":"此刻放置会做什么（见 `DnDEvent.mode`）：例如复制时显示一个加号。","OverlaySlotProps.to":"现在放置会把被拖拽的项放到可排序列表或树中的哪里：例如按树拖拽将进入的文件夹给浮层着色。在所有目标之外，是空位所在的地方，`dropOutside: 'placeholder'`（默认值）会把它们留在那里。当放置不会把它们放进任何列表时为 `null`：在普通放置目标上方、在拒绝它们的列表上方、在 `dropOutside: 'cancel'` 或 `'remove'` 时位于目标之外。已确定的放置执行动画期间，是它落到的位置。",OverlayProps:"浮层组件的 props，用于 `defineProps<OverlayProps>()`。\n\n组件渲染在浮层盒子内部，盒子跟随位置的尺寸（`overlayFit: 'slot'`），并在放置时以动画方式变化。给根元素设置 `width: 100%`（以及 `height: 100%`）以跟随这个尺寸；固定尺寸会保持组件自己的尺寸。",DragPreviewProps:"`DragPreview` 的 props：某一个被拖拽项的默认克隆，用于自行布局多个项的自定义浮层（`overlay` 组件或 provider 的 `#overlay` 插槽），例如 `<DragPreview v-for=\"item in items\" :key=\"item.id\" :id=\"item.id\" />`。\n\n克隆在拿起时生成：抓起的项，以及按放置顺序与它相邻的其他项，数量为 provider 的 `overlayPreviews`（默认 5；限于当时已渲染的那些）。对于其他任何项，`DragPreview` 把它的默认插槽渲染在一个像克隆一样接受 `class` 和 `style` 的元素中；没有默认插槽时什么都不渲染。克隆会填满这个元素，元素的尺寸是该项在拿起时的尺寸，以内联样式设置：用 `style` 修改它（`:style=\"{ width: '100%', height: '100%' }\"`），`style` 会透传；class 无法覆盖它。\n\n在可排序的多项拖拽中（`multiple: 'group'` 或 `'gaps'`），抓起的项以外的项的预览会随放置落到该项的位置上（取消时回到原处），无论布局把它放在哪里：途中会撤销用 `transform` 旋转或缩放的包裹元素，它的尺寸以宽度和高度的方式执行动画。为预览本身设置样式（圆角、阴影）：它的包裹元素留在盒子里。没有克隆的项则改为淡入。放置进某个区域（而不是列表）时，各个预览依次进入该区域，盒子最后进入。","DragPreviewProps.id":"某个被拖拽项的 id：`OverlayProps` 中 `items` 的其中之一。",SelectionStrategy:"- `'toggle'`：选框经过的项会在画选框之前的状态基础上切换；\n- `'select'`：只有选框内的项被选中。",SelectionModifier:"按下时必须按住才能画选框的按键（`KeyboardEvent.key` 或 `.code`）：全部按住，或只按住其中一部分（`'some'`）。","SelectionModifier.keys":"按键，以 `KeyboardEvent.key`（`'Shift'`）或 `.code`（`'KeyA'`）表示。不设置：任何按下都会画选框。","SelectionModifier.method":"`'every'`：必须按住 `keys` 中的所有键；`'some'`：按住其中一个即可。",SelectionAreaOptions:"`makeSelectionArea` 的选项。选框把项选入 provider 的选中集合，也就是多项拖拽和 `selected` 读取的那个（`useDnD().selection`）。`modifier`、`strategy`、`accept` 和 `disabled` 接受值、ref 或 getter（`accept`：值或 ref，函数即规则），并在按下开始画选框时读取；开启 `disabled` 还会取消正在进行的选框。","SelectionAreaOptions.modifier":`按下时必须按住这些键才会画出选框。默认：无，在空白处的任何按下都会画选框。`,"SelectionAreaOptions.strategy":"默认为 `'toggle'`。","SelectionAreaOptions.accept":`选框选中哪些可拖拽元素；与放置目标使用相同的匹配器。`,"SelectionAreaOptions.disabled":"`true`：按下不会画选框。","SelectionAreaOptions.onSelected":`选框结束：获得现在选中的所有 id。`,SelectionAreaReturn:"`makeSelectionArea` 的返回值。","SelectionAreaReturn.isSelecting":`正在画选框：此时渲染它。`,"SelectionAreaReturn.style":`选框矩形元素的样式（绝对定位，相对于容器）。`,SensorDirection:`一次键盘步进的方向键。`,SortablePosition:"可排序列表中的一个位置，用于 `SensorDrag.place()`（以及 `@vue-dnd-kit/actions` 的 `moveItem`）。仅限列表：树通过它们自己的 key 放置项。","SortablePosition.list":"列表的 id（`SortableListOptions.id`）。默认：项当前所在的列表。","SortablePosition.index":`项最终所在的索引，计算时不包含项本身（多项拖拽的整组只算一次）。被限制在列表范围内；默认：末尾。`,SensorActivation:"传感器的输入想要拖拽时，它所请求的内容（`SensorContext.activate()`）。","SensorActivation.target":"输入落在哪里：可拖拽元素内部的某个元素，或某个可拖拽元素的 id。元素必须属于这个 provider；对于 `'pointer'` 拖拽，如果有手柄，它必须位于手柄上，并且不能位于可交互的子元素上（按钮、输入框）；对于 `'keyboard'` 拖拽，它必须是可拖拽元素的焦点目标（手柄，否则是可拖拽元素本身），并且不能是可编辑字段。id 会跳过这些检查：无论输入在哪里，拖拽都从该项开始。","SensorActivation.type":"拖拽如何移动。`'pointer'`（默认）：它跟随传给 `move()` 的坐标点，在那里对目标做命中测试，容器在边缘自动滚动，页面显示抓取光标。`'keyboard'`：它像方向键那样通过 `step()` 和 `place()` 按项移动，目标会被滚动到视野中而不是自动滚动，结束时焦点回到该项上。`Active.sensor` 会告诉你是哪一种。","SensorActivation.point":`拖拽开始的位置，视口坐标。默认：可拖拽元素的中心。`,"SensorActivation.event":"输入事件。它会交给可拖拽元素的 `canDrag`：没有事件时（游戏手柄、程序化拖拽），不会询问 `canDrag`。`pointerType` 为 `'touch'` 时，这次拖拽会成为触摸拖拽（`haptics`）。","SensorActivation.activation":"拖拽开始之前等待的条件（在此之前 `useDnD().status` 为 `'activating'`，并带有进度）。指针类型会先读取可拖拽元素的 `activation` 选项中对应的设置，然后是 provider 的，最后是默认值（鼠标为 4px，在手柄上立即开始；触控笔为 4px；触摸为 200ms 长按，容差 5px）。约束会按原样使用。默认：无，拖拽立即开始。","SensorActivation.onStart":`拖拽已开始，在激活之后：例如捕获指针。`,"SensorActivation.onEnd":`拖拽已结束：它的激活被中止，或者它已放下或被取消（无论由谁）。`,"SensorActivation.onResume":"传感器请求的放置没有发生，拖拽继续（`onBeforeDrop` 返回了 `'continue'`）：`move`、`drop` 和 `cancel` 再次生效。指针传感器会让项跟随指针，直到下一次松开。",SensorDragState:"- `'pending'`：等待激活约束；\n- `'dragging'`：从开始直到放置结果确定或拖拽被取消；\n- `'ended'`：激活被中止，或者拖拽已放下或被取消，无论是由传感器还是其他原因（Escape、隐藏的标签页、`useDnD().cancel()`、provider 卸载）。",SensorStepOptions:"`SensorDrag.step()` 的选项。","SensorStepOptions.event":"按键事件，会交给监听器的 `getKeyboardCoordinates`。默认：该方向键的一个 keydown 事件。","SensorStepOptions.fast":"自由拖拽中更大的步长（与 Shift 相同）。默认：`event.shiftKey`。",SensorDrag:"传感器的一次拖拽，从 `activate()` 开始直到它结束。一旦调用不再适用就会被忽略：开始之前或结束之后的移动、第二次 `drop()`。","SensorDrag.id":`被拖拽项的 id。`,"SensorDrag.type":"拖拽的移动方式，即 `activate()` 所要求的（`SensorActivation.type`）。","SensorDrag.state":`拖拽所处的阶段：等待激活、拖拽中，或已结束。`,"SensorDrag.started":`拖拽已经开始过，即使之后已经结束（指针传感器会吞掉拖拽之后的那次点击）。`,"SensorDrag.move":`输入移动了。等待期间检查激活约束（移动超出容差会中止它）；拖拽期间，拖拽会移到那里。指针拖拽每帧取一个位置；键盘拖拽会在之前的步进完成后立即移动。`,"SensorDrag.step":"键盘拖拽：一次方向键步进，与键盘传感器的方向键效果相同（列表中的下一项、`'droppables'` 模式下下一个接收它的目标，或 `keyboard.step` 像素）。步进会排队：每一步都等前一步渲染完成后才执行，并且当仍有步进尚未完成时，重复按键（`event.repeat`）会被跳过。指针拖拽会忽略它。","SensorDrag.place":"像键盘移动那样，把项放到可排序列表的某个位置（其他列表只有在接收它时才会接纳它），并把拖拽移到它的新位置。没有列表在那里接收它时 resolve 为 `false`。在键盘拖拽中与 `step()` 一样排队。","SensorDrag.drop":"放下：如果激活仍在等待中，则改为中止它。在拖拽结束并落位后 resolve：放置成功时为 `true`，被拒绝（被目标或 `onBeforeDrop`）或没有东西可放下时为 `false`。","SensorDrag.cancel":`取消拖拽（它会飞回原处），或中止等待中的激活。`,SensorContext:`传感器从它所运行的 provider 中得到的内容。`,"SensorContext.props":"provider 的 props（例如 `activation`、`keyboard`）。在需要时再读取：它们可能会变化。","SensorContext.status":`provider 的拖拽状态，无论是哪个传感器在执行拖拽。`,"SensorContext.drag":"provider 的拖拽，等待中或拖拽中，无论是哪个传感器发起的；没有拖拽时为 `null`。传感器之间可以驱动彼此的拖拽：键盘传感器会移动并放下每一次键盘拖拽，例如由“移动”按钮拿起的拖拽（`@vue-dnd-kit/actions`）。","SensorContext.activate":"请求拖拽一个项。provider 会检查：它是否空闲（同一时间只有一次拖拽，放置落位期间也不行）、目标是否是它自己的、未被禁用的可拖拽元素、输入落在哪里（参见 `target`）以及可拖拽元素的 `canDrag`，然后等待激活约束并开始拖拽。返回这次拖拽（等待中；或者没有需要等待的条件时，已经在拖拽中），不能开始拖拽时返回 `null`。","SensorContext.cancel":`取消 provider 的拖拽或等待中的激活，无论是哪个传感器在执行它（Escape、隐藏的标签页）。`,"SensorContext.onWindow":"为 provider 工作的每个窗口运行 `setup`：页面的窗口立即运行，provider 的项所在的每个应用的其他窗口（用 `window.open` 打开、由 Teleport 渲染进去的弹出窗口，见 `DnDState.addWindow`）在它加入时运行。在那里监听那个窗口的输入（`useEventListener(view.document, …)`）：窗口关闭或传感器停止时，这些监听会被清理，`setup` 返回的清理函数也会执行。",Sensor:"发起拖拽的输入：指针、键盘，或你自己的输入（游戏手柄、屏幕上的摇杆、语音、脚本驱动的拖拽）。`setup` 在每个 provider 中运行一次，只在浏览器中运行，位于一个随 provider 结束的副作用作用域中（或者当传感器离开 `sensors`、或调用 `useSensor` 的组件卸载时结束）。用 `useEventListener` 注册监听器，或者返回一个清理函数；届时仍在进行的拖拽会被取消。\n\n要包装一个传感器，用你自己的上下文运行它的 `setup`。`Object.create(context, { activate: { value: … } })` 会保留实时的 getter（`status`、`drag`、`props`）：展开运算符会把它们冻结。","Sensor.name":`用于调试。`,"Sensor.setup":"开始监听输入，每个 provider 一次：想要拖拽时调用 `context.activate()`。可以返回一个清理函数，在传感器停止时运行。",SortableStrategy:"列表如何排布它的项：一列（`'vertical'`）、一行（`'horizontal'`）或自动换行的网格（`'grid'`）。",SortableBehavior:"悬停在某个项上时会发生什么：`'sort'` 腾出位置（中间的项平移），`'swap'` 交换这两个项。",SortablePlaceholder:"拖拽如何显示它将去往哪里：`'item'`，被拖拽项的位置在列表中移动；`'indicator'`，列表保持不动，由 `indicator` 指出放置的位置（由你来画线）。",MultipleMode:"多项拖拽中其他选中项的行为：\n- `'group'`：它们离开原位置，作为连续的占位随当前项一起移动，因此悬停时列表已经显示出放置的结果；\n- `'gaps'`：它们留在原处，直到放置；\n- `'stack'`：它们收进浮层中。\n\n默认浮层会把被拖拽的项沿列表方向排成一列（`'group'`、`'gaps'`；在水平列表中是一行，在网格中是当前项后面的一叠），或者显示当前项加上数量（`'stack'`）。",DropOutside:"在所有目标之外放置时会发生什么：`'placeholder'` 把项留在它们的位置所在处，`'cancel'` 把它们送回原处，`'remove'` 把它们从所在列表中移除。",SortablePutContext:"函数形式的 `group.put` 被调用时收到的参数：将要进入列表的项。","SortablePutContext.keys":`这些项的 key。`,"SortablePutContext.items":"这些项（对于普通的可拖拽元素，是 `createItem` 创建的项）。","SortablePutContext.types":`这些项的类型合在一起。`,"SortablePutContext.from":"来源列表，对于外部的可拖拽元素为 `null`。","SortablePutContext.to":`被询问的列表的 id。`,SortableGroupOptions:`列表的分组：相互交换项的列表，以及项能否离开和进入这个列表。`,"SortableGroupOptions.name":`名称相同的列表和树相互交换项。`,"SortableGroupOptions.pull":"项能否离开这个列表：移动、复制（`'clone'`，面板）或完全不能。","SortableGroupOptions.put":"项能否进入这个列表：`true`（默认）、`false`、项必须具有的一个或多个类型（与放置目标的 `accept` 相同：通过 `acceptMode` 决定全部还是部分），或者一个关于拖拽的函数。",SortableItems:"可排序项的数据源。可写的 ref：库会把每次放置写入其中。只读的数据源（getter、只读 ref、computed：不可变的 store、服务端状态、只能通过 action 修改的 store）：在 `event.preventDefault()` 之后，由你根据 `event.result` 应用每次放置（参见 `SortableDropEvent`）。",SortableDropEvent:"可排序列表或树上的一次放置。它的钩子按顺序运行：`onBeforeDrop` 做决定，`onDrop` 收到通知，然后默认行为把 `result` 写入它所列出的每个列表的 `items`，最后浮层落位。在任一钩子中调用 `preventDefault()` 都会跳过这次写入，这样你就可以自己应用 `result`。","SortableDropEvent.keys":`被拖拽项的 key。`,"SortableDropEvent.items":"落位的项：被拖拽的项、它们的副本（`mode: 'copy'`），或 `createItem` 创建的项（`'insert'`）。","SortableDropEvent.accepted":"放置生效的 key：全部，除非列表或 `onBeforeDrop` 只接受了一部分。","SortableDropEvent.rejected":`飞回原处的 key。`,"SortableDropEvent.from":"拖拽从哪里开始：当前项所在的列表和索引。对于来自外部的普通可拖拽元素，`list` 为 `null`。","SortableDropEvent.to":"没有任何东西落下时，`index` 为 -1：项离开了它们的列表（`e.source.remove()`、`dropOutside: 'remove'`）。","SortableDropEvent.sameList":`放置仍在拖拽开始的那个列表中。`,"SortableDropEvent.mode":"放置会做什么（见 `DragMode`）。","SortableDropEvent.partner":"`mode: 'swap'`：与被拖拽项交换的那个项。它朝相反的方向移动，`from` 是被拖拽项占据的位置（上面的 `to`），`to` 是被拖拽项开始时的位置（上面的 `from`）；在列表之间交换时，它会移入被拖拽项所在的列表。","SortableDropEvent.result":"这次放置改变的每个列表的新项，以列表 id 为键：正是默认写入会放进它们 `items` 中的内容，以新数组的形式提供。移动、复制、新创建的项、部分接受、交换的双方，以及被移除的项（项内部目标中的 `e.source.remove()`、回收区、`dropOutside: 'remove'`）都包含在其中；放置后保持不变的列表则不包含。树的条目是一个新的根数组：变化路径上的节点是副本（`withChildren`），未受影响的子树是共享的，你的节点永远不会被修改。在 `onBeforeDrop` 中，它是钩子做出回答之前的放置结果（返回部分 key 会改变它）；`onDrop` 收到的是最终结果。","SortableDropEvent.preventDefault":"跳过默认写入，对 `result` 中的每个列表都跳过（只写入其中一部分会丢失或重复项）。在 `onDrop` 中，或在异步的 `onBeforeDrop` resolve 之前自己应用 `result`，浮层就会按新的顺序落位。如果哪里都没有应用，列表保持原样，浮层飞回原处（副本和新创建的项还没有位置，会淡出）。","SortableDropEvent.defaultPrevented":"在 `onBeforeDrop` 或 `onDrop` 中调用过 `preventDefault()`。","SortableDropEvent.external":"来自页面之外的拖拽（`external`）：它携带的内容，包括它的数据（它已被放下）。",SortableIndicator:"使用 `placeholder: 'indicator'` 时放置的位置：列表不移动，由你来画线。","SortableIndicator.list":`放置进入的列表（或树）的 id。`,"SortableIndicator.index":`在渲染出的列表中的插入位置。`,"SortableIndicator.key":"指示器所依附的项；在空列表中为 `null`。","SortableIndicator.side":"插入线位于 `key` 的哪一侧。`'inside'`（树）：悬停在一个接收被拖拽节点的行的中间，放置会进入这一行，成为它的第一个子节点。`'swap'`（`behavior: 'swap'`）：`key` 是放置时与之交换的项；标记该项本身。","SortableIndicator.depth":`树：被放下的节点将得到的深度（根节点为 0），例如用来缩进插入线。`,"SortableIndicator.parentKey":"树：被放下的节点将得到的父节点，在根层级时为 `null`。",SortableListOptions:"`makeSortableList` 的选项。一个组件可以创建多个列表（和树）：组件中渲染的每个项都会加入元素包含它的最内层列表。\n\n选项接受值、ref 或 getter（`overlay`、`overOverlay`、`dropAnimation`、`overDropAnimation`、`animation`：值或 ref），并在列表需要时读取，所以变化最迟在下一次拖拽时生效。例外：`id` 和 `group` 只在创建列表时读取一次；`items` 就是模型本身；函数（`getKey`、`filter`、`clone`、`createItem`、各个回调）按原样传入。","SortableListOptions.items":"数据的唯一来源。可写的 ref 会在放置时、紧接在 `onDrop` 之后接收新数组。只读的数据源（getter、只读 ref、computed）则不能：调用 `event.preventDefault()`，自己应用 `event.result`。如果那里的放置被留给库处理，开发构建会发出警告，而这样的放置什么都不会改变。","SortableListOptions.getKey":"默认：`item.id`；对于原始值，则是项本身。也用于为 `makeSortableItem({ item })` 生成 key。","SortableListOptions.filter":"只显示它返回 `true` 的项（搜索、标签）：`items`（返回的那个）包含这些项，拖拽在它们之间排序。其余项在源数组中保持原位：放置会写入整个数组，每个隐藏项仍跟在它原先跟随的显示项之后（那一项被移动时，跟在最近的留在原处的项之后）。响应式：它读取的东西（搜索词的 ref）立即生效。`e.to.index` 和 `activeIndex` 按显示的项计数。","SortableListOptions.id":"默认：`useId()`，在服务端和客户端渲染之间保持稳定。只读取一次。","SortableListOptions.label":"人们对列表的称呼：屏幕阅读器文本会说出它，而不是列表的 id（`position 2 of 5 in Garden`）。","SortableListOptions.data":"关于这个列表作为放置目标的任何信息：拖拽位于它上方时，事件以 `over.data` 携带它。","SortableListOptions.activation":"在这个列表的项上按下时如何开始拖拽，替代 provider 的 `activation`（项自己的优先）。在按下开始时读取。","SortableListOptions.overlay":"这个列表中项的浮层组件（项自己的 `overlay` 优先）。它接收 `OverlayProps`，并在整个拖拽过程中保持不变，经过其他列表时也是如此，除非拖拽下方的目标有自己的浮层（`overOverlay`）。在拖拽过程中切换的 ref 会立即替换它。","SortableListOptions.overOverlay":"当这个列表接受的拖拽位于它上方时浮层显示什么，无论拖拽来自哪个列表：一个获得 `OverlayProps`、并把拖拽自己的浮层作为默认插槽的组件（见 `DroppableOptions.overOverlay`）。实时读取。","SortableListOptions.dropAnimation":"这个列表中项的拖拽结束时浮层如何落位，替代 provider 的 `dropAnimation`（项自己的优先；放置目标的优先于两者）。在放置时读取。","SortableListOptions.overDropAnimation":"浮层被放进这个列表时如何落位，无论它来自哪个列表：优先于被拖拽项和 provider 的 `dropAnimation`。在放置时读取。","SortableListOptions.modifiers":"这个列表中项的拖拽修饰器，在 provider 的 `modifiers` 之后应用（项自己的 `modifiers` 优先）：例如用 `[restrictToVerticalAxis]` 让垂直列表的项保持在轴上。在拖拽开始时读取。","SortableListOptions.axis":"把这个列表中项的拖拽锁定在一个轴上：垂直列表用 `'y'`，水平列表用 `'x'`（项自己的 `axis` 优先）。锁定在修饰器之后执行，所以无论修饰器做什么，锁定都成立。在拖拽开始时读取。","SortableListOptions.group":`分组名称相同的列表会互相交换项。默认：自成一组。只读取一次。`,"SortableListOptions.acceptMode":"多种类型项的多项拖拽：全部（`'all'`，默认）还是部分（`'some'`）项必须被接受（`group.put`）。","SortableListOptions.strategy":"默认为 `'vertical'`。","SortableListOptions.behavior":"`'swap'`：被拖拽的项与被悬停的项实时交换位置；移回它上方或移出列表会还原。同一分组中都设置了交换的列表之间会互相交换项：被悬停的项移到被拖拽项的位置，所以它必须能离开自己的列表（`group.pull: true`）并进入被拖拽项的列表（`group.put`）。多项拖拽会排序而不是交换。默认为 `'sort'`。","SortableListOptions.placeholder":"`'indicator'`：列表不移动，由 `indicator` 指出放置的位置。默认为 `'item'`。","SortableListOptions.multiple":"从这个列表开始的拖拽的多项拖拽模式。默认为 `'group'`。在拖拽开始时读取。","SortableListOptions.sort":"`false`：项不能在这个列表内部重新排序（面板）。","SortableListOptions.clone":"创建副本（`pull: 'clone'`、复制修饰键）。复制时必需。","SortableListOptions.createItem":"接收来自外部的普通可拖拽元素：创建要插入的项。使用键盘时，朝列表方向按方向键即可把可拖拽元素放进来（与它平齐，就像在列表之间移动那样），之后新创建的项会像其他项一样逐个位置移动。\n\n来自页面之外的拖拽（`external`）会被询问两次：拖拽进行时，询问用来显示它将去往哪里的项（此时只知道 `active.external.fileTypes` 和 `types`）；放置时，带着它的数据（`active.external.ready`），询问要插入的内容。返回一组项时，它们会全部插入到占位所在的位置：每个文件一项。","SortableListOptions.external":"接收来自页面之外的拖拽：文件、链接、文本（见 `ExternalAccept`）。列表像为普通可拖拽元素那样为它们腾出位置，这需要 `createItem`。从应用另一个窗口拖进来的同一分组的项（`native`）两个选项都不需要：它们以自身进入。值、ref 或 getter，实时读取。","SortableListOptions.dropOutside":"放在所有目标之外时：把项留在占位所在的地方、取消，或者移除它们。默认为 `'placeholder'`（使用 `placeholder: 'indicator'` 时为 `'cancel'`）。在放置时读取。","SortableListOptions.animation":"这个列表的 FLIP 动画；默认：provider 的 `animation`。值或 ref（函数即自定义动画）。","SortableListOptions.animateChanges":"为非拖拽引起的 `items` 变化添加动画：被添加、删除、移动和过滤的项（参见 `AutoAnimation`）。默认：provider 的 `animateChanges`，除非在那里设置，否则关闭。在 `items` 变化时读取。","SortableListOptions.animateSize":"列表自身的尺寸跟随它的项：当拖拽带入或带走一个项时（以及放置时，和 `animateChanges` 展示的变化中），它以 `animation` 的时长和缓动增大或缩小到新尺寸，而不是跳变，周围的内容也随之移动。默认 `true`；`false` 让它跳变。每次变化时读取。","SortableListOptions.autoScroll":"为这个列表的滚动容器覆盖 provider 的 `autoScroll`。在拖拽开始时读取。","SortableListOptions.dropzone":`替列表接收放置的元素，默认是列表元素本身：例如包围一个短卡片列表的整列，这样在最后一张卡片下方松开的卡片仍然会落进列表（落到末尾）。项仍然留在列表元素中。`,"SortableListOptions.disabled":"`true`：它的项不能被拖拽，它也不接受任何项。","SortableListOptions.onBeforeDrop":"在放置进入这个列表之前、以及 `dropOutside: 'remove'` 移出它的项之前询问：`false` 拒绝（项飞回原处），返回部分 key 则只接受这些项。可以是异步的：浮层停在被放下的位置等待。抛出错误也会拒绝这次放置。关于 `result` 和 `preventDefault`，参见 `SortableDropEvent`。","SortableListOptions.onDrop":"放置进入这个列表并被接受后、写入之前调用：`items` 仍是旧顺序，`event.result` 是新顺序。同步执行：它返回后紧接着就会写入，除非它调用了 `event.preventDefault()`。当项被移除时（`to.index` 为 -1），也会在项所来自的列表上调用。",SortableListReturn:"`makeSortableList` 的返回值。","SortableListReturn.id":"列表的 id：`id` 选项，或为它生成的 id。","SortableListReturn.items":`草稿顺序：渲染它，而不是源数组。`,"SortableListReturn.isOver":`有拖拽位于列表上方。`,"SortableListReturn.isAccepting":`正在拖拽某个东西，并且这个列表接受它。`,"SortableListReturn.indicator":"指示器模式：放置在这个列表中的位置；不在这里时为 `null`。","SortableListReturn.activeKey":"虚拟化器必须保持挂载的行：位置在这个列表中时（副本、新创建的项）是该位置，否则是被拖拽的项；没有拖拽时为 `null`。","SortableListReturn.activeIndex":`当前项在这个列表草稿中的索引，不在这里时为 -1。`,"SortableListReturn.activeSize":`拖拽开始时被拖拽项的尺寸：例如用作它所占虚拟行的尺寸。`,"SortableListReturn.captureLayout":`为库没有引起的布局变化添加动画（例如虚拟化器重新测量）。`,SortableItemOptions:"传入 `id` 或 `item`（两者都传时 `id` 优先）。可排序的 key 必须来自数据：自动生成的 id 会在组件重新创建时（移到另一个列表、被虚拟列表回收）发生变化，拖拽就会丢失这个项。\n\n除 `canDrag` 外，选项都接受值、ref 或 getter（`overlay`、`dropAnimation`：值或 ref），含义与 `makeDraggable` 上的相同。没有 `keyboardMode`：键盘按位置逐个移动可排序项。","SortableItemOptions.id":`项在其列表中的 key。在虚拟列表中，getter 能让它保持最新。`,"SortableItemOptions.item":"这个元素渲染的项，例如 `() => props.task`。它的 key 来自所属列表（或树）的 `getKey`，默认为 `item.id`。","SortableItemOptions.overlay":"这个项的浮层组件；优先于列表的 `overlay`。在拖拽过程中切换的 ref 会立即替换它。","SortableItemOptions.dropAnimation":"这个项的拖拽结束时浮层如何落位；优先于列表的 `dropAnimation`。在放置时读取。","SortableItemOptions.modifiers":"这个项的拖拽修饰器，在 provider 的之后应用；优先于列表的 `modifiers`。","SortableItemOptions.axis":"把这个项的拖拽锁定在一个轴上（`'x'`、`'y'`）；优先于列表的 `axis`。","SortableItemOptions.handle":`项内部用于开始拖拽的元素或选择器（它也会得到相关属性）。`,"SortableItemOptions.disabled":"`true`：这个项不能被拖拽（与禁用列表中的每个项一样）。","SortableItemOptions.type":"它的一个或多个类型，用于 `group.put` 规则和放置目标的 `accept`。默认：它所在列表的分组名称。","SortableItemOptions.data":"拖拽要携带的任何内容：事件和放置目标以 `active.data` 读取它。","SortableItemOptions.label":"人们对项的称呼：屏幕阅读器文本会说出它，而不是项的 key（`Picked up Tomato at position 2 of 5 in Garden`）。事件以 `active.label` 和在 `items` 中携带它。","SortableItemOptions.activation":"覆盖它所在列表（或树）的 `activation` 以及 provider 的。在按下开始时读取。","SortableItemOptions.canDrag":`额外的关卡，例如只在按住某个键时才能拖拽。`,"SortableItemOptions.attributes":"设置 role/tabindex/aria-* 属性（默认 `true`），永远不会覆盖用户自己设置的。实时生效：关闭后，库设置的属性会被移除。","SortableItemOptions.native":"用鼠标拖拽它就是浏览器自己的拖拽，可以离开页面（见 `DraggableOptions.native`）。它还携带这个项：应用另一个窗口中同一分组的列表会接收它，一旦被接收，它就离开这个列表（`'move'`）。",SortableItemReturn:"`makeSortableItem` 的返回值。","SortableItemReturn.isDragging":`这个项正在被拖拽（对多项拖拽中的其他项也为 true），或者它的浮层仍在落位。`,"SortableItemReturn.isPlaceholder":"这个元素是被拖拽项将落入的位置：当前项的位置；在多项拖拽的 `'group'` 模式下，还包括随它一起移动的各项的位置。","SortableItemReturn.selected":`它在 provider 的选中集合中：拖拽一个选中的项会带上全部。对它赋值即可选中或取消选中。`,"SortableItemReturn.indicator":"指示器模式：列表的 `indicator` 依附于这个项时为该值，否则为 `null`。`side` 说明插入线的位置；在树中，`depth` 和 `parentKey` 说明放置落在哪里（`side: 'inside'`：放进这个项）。","SortableItemReturn.index":`在渲染出的草稿中的索引，未知时为 -1。`,TreeNesting:"树中的拖拽如何选择深度：`'offset'`，按横向移动的距离（每级 `indentation`）；`'hover'`，悬停在某行的中间，该行会把它作为子节点接收；`'both'`。",FlatNode:"树中一个可见的节点，与树的 `items` 列出的一致：按顺序渲染它们，并按 `depth` 缩进。","FlatNode.key":"节点的 key（`getKey`）。","FlatNode.item":`你的节点。`,"FlatNode.depth":`它的深度：根节点为 0。被拖拽的节点使用它的预计深度。`,"FlatNode.parentKey":"父节点的 key；根节点为 `null`。","FlatNode.index":`在兄弟节点中的索引。`,"FlatNode.hasChildren":`它有子节点，无论是否显示。`,"FlatNode.collapsed":"它的子节点被隐藏了（它的 key 在 `collapsed` 中）。",TreeProjection:`被拖拽的节点将落到树中的哪里。`,"TreeProjection.depth":`它将得到的深度（根节点为 0）。`,"TreeProjection.parentKey":"它将归入的父节点；在根层级时为 `null`。",SortableTreeDropEvent:"树的放置事件。`index` 是在 `parentKey` 之下兄弟节点中的位置（`from`：移动之前；`to`：移动之后，此时节点已从原位置移除）。对于根节点以及来自其他列表的项，`from.parentKey` 为 `null`。多项拖拽会把 `keys`（各自带着子树）并排移动：`from` 是带领这次拖拽的节点（抓起的节点，或它所在的那个选中节点）原来的位置，`to` 是其中第一个节点落下的位置。复制（`mode: 'copy'`）会把节点留在原处，并插入 `items`，即它们的副本；普通可拖拽元素（`mode: 'insert'`）则插入 `createItem` 创建的节点。","SortableTreeDropEvent.from":`带领拖拽的节点原来所在的位置：它所在的树、它在兄弟节点中的索引、它的父节点。`,"SortableTreeDropEvent.to":`第一个被放下的节点落到的位置：它所在的树、它在新兄弟节点中的索引、它的新父节点。`,SortableTreeOptions:"`makeSortableTree` 的选项。多项拖拽会把选中的节点作为一个整体移动，各自带着子树，移到同一个位置和深度（按文档顺序）；位于另一个选中节点内部的选中节点会随其子树一起移动。抓起的节点也是如此（与 VS Code 一样）：它留在它所在的那个选中节点内部，跟随该节点及其子树一起移动，而浮层显示的仍是抓起的那一行。`canNest` 和 `maxDepth` 作用于整个整体。\n\n其他选项的含义与 `makeSortableList` 上的相同。它们接受值、ref 或 getter（`overlay`、`overOverlay`、`animation`、`dropAnimation`、`overDropAnimation`：值或 ref），并在树需要时读取，所以变化最迟在下一次拖拽时生效。例外：`id` 和 `group` 只在创建树时读取一次；`items` 就是模型本身；函数（`getKey`、`getChildren`、`setChildren`、`canNest`、`clone`、`createItem`、各个回调）按原样传入。","SortableTreeOptions.items":"根节点。可写的 ref：放置时，库会给发生变化的节点设置新的子节点（`setChildren`），并写入一个新的根数组。只读的数据源（getter、只读 ref、computed）：调用 `event.preventDefault()`，自己应用 `event.result`（与 `SortableListOptions.items` 相同）。","SortableTreeOptions.getKey":"默认：`node.id`。也用于为 `makeSortableItem({ item })`、副本和新创建的节点生成 key。","SortableTreeOptions.getChildren":"节点的子节点。默认：`node.children`。","SortableTreeOptions.setChildren":"默认写入如何给节点设置新的子节点。默认：`node.children = children`。","SortableTreeOptions.withChildren":"带有 `children` 的 `node` 副本，用于 `event.result`：一棵保留你原有节点不变的新树（默认写入仍通过 `setChildren` 完成）。默认：通过 `setChildren` 设置了子节点的 `{ ...node }`（没有 `setChildren` 时为 `{ ...node, children }`）。对于类实例，以及需要比浅拷贝更多处理的节点，传入它。","SortableTreeOptions.id":"默认：`useId()`，在服务端和客户端渲染之间保持稳定。只读取一次。","SortableTreeOptions.label":`人们对树的称呼：屏幕阅读器文本会说出它，而不是树的 id。`,"SortableTreeOptions.data":"关于这棵树作为放置目标的任何信息：拖拽位于它上方时，事件以 `over.data` 携带它。","SortableTreeOptions.activation":"在这棵树的行上按下时如何开始拖拽，替代 provider 的 `activation`（行自己的优先）。","SortableTreeOptions.overlay":"这棵树中行的浮层组件（行自己的 `overlay` 优先）。在拖拽过程中切换的 ref 会立即替换它。","SortableTreeOptions.overOverlay":"当这棵树接受的拖拽位于它上方时浮层显示什么（见 `SortableListOptions.overOverlay`）。它的 `to` prop 说明放置会嵌套到哪里。","SortableTreeOptions.dropAnimation":"这棵树中行的拖拽结束时浮层如何落位（见 `SortableListOptions.dropAnimation`）。","SortableTreeOptions.overDropAnimation":"浮层被放进这棵树时如何落位（见 `SortableListOptions.overDropAnimation`）。","SortableTreeOptions.modifiers":"这棵树中行的拖拽修饰器，在 provider 的 `modifiers` 之后应用（行自己的 `modifiers` 优先）：例如 `[restrictToVerticalAxis]`。在拖拽开始时读取。锁定轴向后仍然可以嵌套：此时深度来自悬停在某一行的中间。","SortableTreeOptions.axis":"在修饰器之后，把这棵树中行的拖拽锁定在一个轴上（行自己的 `axis` 优先）。使用 `'y'` 时行仍然可以嵌套：此时深度来自悬停在某一行的中间。在拖拽开始时读取。","SortableTreeOptions.group":`分组名称相同的列表和树会互相交换项。默认：自成一组。只读取一次。`,"SortableTreeOptions.acceptMode":"多种类型项的多项拖拽：全部（`'all'`，默认）还是部分（`'some'`）项必须被接受（`group.put`）。","SortableTreeOptions.indentation":`每一级深度对应的水平偏移像素数。默认 24。`,"SortableTreeOptions.nesting":`如何选择深度：水平偏移、悬停在某一行的中间，或两者兼用（默认）。`,"SortableTreeOptions.placeholder":"`'item'`（默认）：被拖拽的节点以预测的深度在行之间移动。`'indicator'`：树不移动；`indicator`（在树上以及每一行的 `makeSortableItem` 上）指出放置的位置，以及它的 `depth` 和 `parentKey`，插入线由你来画。此时放到外面会取消。","SortableTreeOptions.maxDepth":`允许的最大深度（根节点为 0）。被拖拽节点自己的后代也计算在内。`,"SortableTreeOptions.canNest":"`node` 能否放到 `parent` 之下；多项拖拽时会对每个被拖拽的节点询问。","SortableTreeOptions.collapsed":`子节点被隐藏的节点的 key。`,"SortableTreeOptions.clone":"创建副本（`group.pull: 'clone'`、复制修饰键）。复制时必需。返回带有整棵子树的副本：被复制的文件夹会保留它的子节点。副本及其每个后代都需要自己的 key（用 `getKey` 读取），就像树中的每个节点一样。","SortableTreeOptions.createItem":"接收来自外部的普通可拖拽元素：在预测的位置和深度创建要插入的节点（`canNest` 和 `maxDepth` 对它同样适用）。使用键盘时，朝树的方向按方向键即可把可拖拽元素放进来，与它将插入其前方的那一行平齐，之后方向键会像移动其他节点一样移动这个节点。来自页面之外的拖拽（`external`）会被询问两次，拖拽进行时和放置时各一次（见列表的 `createItem`）；一个为每个文件带一个子节点的文件夹节点可以容纳多个文件。","SortableTreeOptions.external":"接收来自页面之外的拖拽：文件、链接、文本（见 `ExternalAccept`），配合 `createItem`。从应用另一个窗口拖进来的同一分组的节点以自身进入。值、ref 或 getter，实时读取。","SortableTreeOptions.dropOutside":"放在所有目标之外时：把节点留在占位所在的地方、取消，或者移除它们。默认为 `'placeholder'`（使用 `placeholder: 'indicator'` 时为 `'cancel'`）。在放置时读取。","SortableTreeOptions.animation":"这棵树的 FLIP 动画；默认：provider 的 `animation`。值或 ref（函数即自定义动画）。","SortableTreeOptions.animateChanges":"与 `SortableListOptions` 中相同，作用于可见的行：被添加、删除或移动的节点，以及节点展开或折叠时显示或隐藏的行（`collapsed`）。","SortableTreeOptions.animateSize":"树自身的尺寸跟随它的行，与列表一样（`animateSize`）。默认 `true`。","SortableTreeOptions.autoScroll":"为这棵树的滚动容器覆盖 provider 的 `autoScroll`。在拖拽开始时读取。","SortableTreeOptions.dropzone":"与 `SortableListOptions` 中相同：替树接收放置的元素，默认是树自己的元素。","SortableTreeOptions.disabled":"`true`：它的行不能被拖拽，它也不接受任何项。","SortableTreeOptions.onBeforeDrop":"与 `SortableListOptions` 中相同。","SortableTreeOptions.onDrop":"与 `SortableListOptions` 中相同：在写入之前调用，`event.preventDefault()` 会跳过写入。",SortableTreeReturn:"`makeSortableTree` 的返回值。","SortableTreeReturn.id":"树的 id：`id` 选项，或为它生成的 id。","SortableTreeReturn.items":`按草稿顺序排列的可见节点；当前节点带有它的预测深度。`,"SortableTreeReturn.projected":"当前节点将会落到哪里，不在这棵树中时为 `null`。","SortableTreeReturn.indicator":"指示器模式：放置的位置，以及它的 `depth` 和 `parentKey`；不在这里时为 `null`。","SortableTreeReturn.isOver":`有拖拽位于树上方。`,"SortableTreeReturn.isAccepting":`有东西正在被拖拽，并且这棵树接收它。`,"SortableTreeReturn.activeKey":`虚拟化器必须保持挂载的行：当占位位于这棵树中时，是占位所在的行（被拖拽的节点、抓起的节点所在的那个选中节点、副本、新创建的节点），否则是被拖拽的节点。`,"SortableTreeReturn.activeIndex":"`activeKey` 在 `items` 中的索引，不在这里时为 -1。","SortableTreeReturn.activeSize":`拖拽开始时被拖拽行的尺寸。`,"SortableTreeReturn.captureLayout":`为不是本库引起的布局变化添加动画（例如虚拟化器重新测量）。`};export{e as default};